152	export function getPercentileRank(score: number): number {
153	  // Simulated distribution based on CRO industry data
154	  if (score >= 90) return 97;
155	  if (score >= 80) return 88;
156	  if (score >= 70) return 72;
157	  if (score >= 60) return 55;
158	  if (score >= 50) return 38;
159	  if (score >= 40) return 22;
160	  if (score >= 30) return 12;
161	  return 5;
162	}
