17	interface UrlInputProps {
18	  showPageType?: boolean;
19	  buttonText?: string;
20	  size?: "default" | "lg";
21	  className?: string;
22	  onSubmit?: (url: string, pageType: PageType) => void;
23	}
24	
25	export function UrlInput({
26	  showPageType = false,
27	  buttonText = "Analyze Now",
28	  size = "default",
29	  className,
30	  onSubmit,
31	}: UrlInputProps) {
32	  const [url, setUrl] = useState("");
33	  const [pageType, setPageType] = useState<PageType>("landing");
34	  const navigate = useNavigate();
35	
36	  const handleSubmit = (e: React.FormEvent) => {
37	    e.preventDefault();
38	    if (!url.trim()) return;
39	
40	    if (onSubmit) {
41	      onSubmit(url, pageType);
42	    } else {
43	      navigate(`/scan?url=${encodeURIComponent(url)}&type=${pageType}`);
44	    }
45	  };
46	
47	  const isLarge = size === "lg";
48	
49	  return (
50	    <form onSubmit={handleSubmit} className={cn("w-full", className)}>
51	      <div className={cn("flex gap-2", isLarge ? "flex-col sm:flex-row" : "flex-row")}>
52	        <div className="relative flex-1">
53	          <Input
54	            type="url"
55	            placeholder="https://your-website.com/landing-page"
56	            value={url}
57	            onChange={(e) => setUrl(e.target.value)}
58	            className={cn(
59	              "border-slate-200 bg-white pr-4 pl-4 text-foreground placeholder:text-slate-400 focus-visible:ring-primary/20 focus-visible:border-primary",
60	              isLarge ? "h-14 text-base rounded-xl" : "h-10 text-sm rounded-lg"
61	            )}
62	          />
63	        </div>
64	        {showPageType && (
65	          <Select value={pageType} onValueChange={(v) => setPageType(v as PageType)}>
66	            <SelectTrigger
67	              className={cn(
68	                "w-40 border-slate-200 bg-white",
69	                isLarge ? "h-14 rounded-xl" : "h-10 rounded-lg"
70	              )}
71	            >
72	              <SelectValue placeholder="Page type" />
73	            </SelectTrigger>
74	            <SelectContent>
75	              {PAGE_TYPES.map((type) => (
76	                <SelectItem key={type.value} value={type.value}>
77	                  {type.label}
78	                </SelectItem>
79	              ))}
80	            </SelectContent>
81	          </Select>
82	        )}
83	        <Button
84	          type="submit"
85	          className={cn(
86	            "shrink-0 font-semibold",
87	            isLarge
88	              ? "h-14 px-8 text-base rounded-xl"
89	              : "h-10 px-5 text-sm rounded-lg"
90	          )}
91	        >
92	          <ScanLine className={cn("mr-2", isLarge ? "h-5 w-5" : "h-4 w-4")} />
93	          {buttonText}
94	        </Button>
95	      </div>
96	    </form>
97	  );
